import{_ as a,o as s,c as t,a0 as i}from"./chunks/framework.BI4vEdDZ.js";const n="/assets/site-media/Custom-Denim-Jeans-from-China-factory-.png",h=JSON.parse('{"title":"About Us","description":"Learn about KiKi Jeans, a custom denim jeans manufacturer serving wholesale suppliers, private label brands and retail chains.","frontmatter":{"title":"About Us","description":"Learn about KiKi Jeans, a custom denim jeans manufacturer serving wholesale suppliers, private label brands and retail chains."},"headers":[],"relativePath":"about-us.md","filePath":"about-us.md"}'),r={name:"about-us.md"};function o(c,e,p,l,d,u){return s(),t("div",null,[...e[0]||(e[0]=[i('<section class="about-hero"><div><p class="eyebrow">About KiKi Jeans</p><h1>Custom Denim Built for Brands That Need Reliable Production</h1><p> KiKi Jeans is a professional denim jeans manufacturer focused on custom jeans, private label denim, technical washing and bulk OEM/ODM production for wholesale suppliers, retail chains and growing apparel brands. </p><div class="button-row"><a class="btn primary" href="/assets/site-media/wechat.jpg">Start a Denim Project</a><a class="btn outline" href="/how-we-make-it.html">See How We Make It</a></div></div><img src="'+n+'" alt="KiKi Jeans custom denim models"></section><section class="about-section"><div class="about-copy"><p class="eyebrow">Who We Are</p><h2>A Factory Partner for High-End Custom Jeans</h2><p> Based in Zhongshan, Guangzhou, KiKi Jeans supports brands from concept development to boutique-ready production. Our team helps transform design references, fits, washes, labels and packaging ideas into practical denim products that can be sampled, refined and produced at scale. </p><p> We work with clients who need more than basic manufacturing. Our value is in trend-driven denim development, heavy-wash craftsmanship, strict quality control and steady communication through every production stage. </p></div><div class="about-stat-grid"><article><strong>20+</strong><span>Years of denim manufacturing experience</span></article><article><strong>500+</strong><span>Employees supporting stable production</span></article><article><strong>100 pcs</strong><span>MOQ per style for flexible brand orders</span></article><article><strong>OEM/ODM</strong><span>Custom design, wash, fit and label service</span></article></div></section><section class="about-section about-dark"><div><p class="eyebrow">What We Do</p><h2>From Sample Development to Bulk Denim Production</h2></div><div class="about-card-grid"><article><h3>Custom Jeans Manufacturing</h3><p>Men&#39;s and women&#39;s jeans, denim shorts, skirts, jackets and private label denim programs.</p></article><article><h3>Technical Wash Development</h3><p>Specialized washes, distressing, whiskers, grinding and premium effects for market-ready styles.</p></article><article><h3>Brand Customization</h3><p>Custom labels, hang tags, hardware, packaging and size details matched to your brand identity.</p></article><article><h3>Quality Control</h3><p>Inspection across fabric, cutting, sewing, washing, finishing and packing before shipment.</p></article></div></section><section class="about-section"><div class="about-copy"><p class="eyebrow">Why Brands Choose Us</p><h2>Practical Denim Expertise, Not Just Production Capacity</h2><p> KiKi Jeans is built for buyers who care about product appearance, fit, wash quality and dependable delivery. We help clients test ideas quickly, confirm samples clearly and move into bulk production with fewer surprises. </p></div><div class="about-values"><span>Trend-driven R&amp;D</span><span>Low MOQ support</span><span>Fast sample development</span><span>Private label service</span><span>Strict QC standards</span><span>Worldwide shipping support</span></div></section>',4)])])}const b=a(r,[["render",o]]);export{h as __pageData,b as default};
